import{_ as a,o as t,c as o,a as i}from"./app.DLiRGumz.js";const m=JSON.parse('{"title":"Atoms Clean/Deploy Knowledge Base","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/ATOMS_CLEAN_DEPLOY_KNOWLEDGE_BASE.md","filePath":"contracts/ATOMS_CLEAN_DEPLOY_KNOWLEDGE_BASE.md","lastUpdated":1771758855000}'),n={name:"contracts/ATOMS_CLEAN_DEPLOY_KNOWLEDGE_BASE.md"};function l(d,e,c,r,s,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="atoms-clean-deploy-knowledge-base" tabindex="-1">Atoms Clean/Deploy Knowledge Base <a class="header-anchor" href="#atoms-clean-deploy-knowledge-base" aria-label="Permalink to &quot;Atoms Clean/Deploy Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document is the cross-repo baseline for <code>atoms</code> clean/deploy behavior and environment discovery. It codifies the canonical path and operational defaults used by this repo&#39;s automation and docs.</p><h2 id="_81-cross-repo-clean-deploy-inventory" tabindex="-1">81) Cross-Repo Clean/Deploy Inventory <a class="header-anchor" href="#_81-cross-repo-clean-deploy-inventory" aria-label="Permalink to &quot;81) Cross-Repo Clean/Deploy Inventory&quot;">​</a></h2><h3 id="atoms-mcp-prod" tabindex="-1"><code>../atoms-mcp-prod</code> <a class="header-anchor" href="#atoms-mcp-prod" aria-label="Permalink to &quot;`../atoms-mcp-prod`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>Source</th><th>Status</th></tr></thead><tbody><tr><td>Clean entrypoint</td><td><code>Taskfile.yml</code> -&gt; <code>clean</code> target</td><td>Canonical</td></tr><tr><td>Clean CLI command</td><td><code>cli.py</code> -&gt; <code>clean()</code> (<code>atoms clean</code>)</td><td>Canonical</td></tr><tr><td>Vercel deployment config</td><td><code>vercel.json</code></td><td>Canonical</td></tr><tr><td>Deployment guide</td><td><code>docs/DEPLOYMENT_GUIDE.md</code></td><td>Canonical</td></tr><tr><td>Cloud Run helper</td><td><code>scripts/deploy_gcp.sh</code></td><td>Non-canonical (legacy helper)</td></tr></tbody></table><h3 id="agentapi-atomsagent" tabindex="-1"><code>../agentapi/atomsAgent</code> <a class="header-anchor" href="#agentapi-atomsagent" aria-label="Permalink to &quot;`../agentapi/atomsAgent`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>Source</th><th>Status</th></tr></thead><tbody><tr><td>Cloud Run command surface</td><td><code>src/atomsAgent/cli/commands/cloud_run.py</code></td><td>Canonical</td></tr><tr><td>Cloud Run deploy docs</td><td><code>docs/guides/deployment.md</code></td><td>Canonical</td></tr><tr><td>Infrastructure target</td><td><code>infrastructure/README.md</code> (IAC: SST Ion for Cloud Run)</td><td>Canonical</td></tr><tr><td>Legacy deploy path</td><td>Pulumi references removed from current flow</td><td>Deprecated</td></tr></tbody></table><h2 id="_82-canonical-clean-deploy-path-as-used-by-thegent" tabindex="-1">82) Canonical Clean/Deploy Path (as used by thegent) <a class="header-anchor" href="#_82-canonical-clean-deploy-path-as-used-by-thegent" aria-label="Permalink to &quot;82) Canonical Clean/Deploy Path (as used by thegent)&quot;">​</a></h2><h3 id="canonical-path-recommendation" tabindex="-1">Canonical path recommendation <a class="header-anchor" href="#canonical-path-recommendation" aria-label="Permalink to &quot;Canonical path recommendation&quot;">​</a></h3><p>For shared operations documented in thegent, <strong>prefer Vercel-first clean/deploy for <code>atoms-mcp-prod</code> and SST/Cloud Run for <code>atomsAgent</code></strong>.</p><ul><li>Canonical for MCP server: <code>../atoms-mcp-prod</code><ul><li>Clean via <code>atoms clean</code> (<code>../atoms-mcp-prod/cli.py</code> / <code>Taskfile.yml</code>).</li><li>Deploy via Vercel (<code>vercel.json</code> + <code>docs/DEPLOYMENT_GUIDE.md</code>).</li></ul></li><li>Canonical for Agent API service: <code>../agentapi/atomsAgent</code><ul><li>Deploy via <code>atoms-agent cloud-run deploy</code> (<code>src/atomsAgent/cli/commands/cloud_run.py</code>).</li><li>IAC is driven by SST (<code>infrastructure/README.md</code>).</li></ul></li></ul><h3 id="deprecated-legacy-paths" tabindex="-1">Deprecated/legacy paths <a class="header-anchor" href="#deprecated-legacy-paths" aria-label="Permalink to &quot;Deprecated/legacy paths&quot;">​</a></h3><ul><li>Legacy Pulumi flows and older Cloud Run wrappers are explicitly treated as non-canonical and should not be used for standard delivery paths.</li></ul><h2 id="_83-env-discovery-contract-institutionalized" tabindex="-1">83) Env-Discovery Contract (Institutionalized) <a class="header-anchor" href="#_83-env-discovery-contract-institutionalized" aria-label="Permalink to &quot;83) Env-Discovery Contract (Institutionalized)&quot;">​</a></h2><h3 id="contract-objective" tabindex="-1">Contract objective <a class="header-anchor" href="#contract-objective" aria-label="Permalink to &quot;Contract objective&quot;">​</a></h3><p>Any tooling that needs Atoms deployment secrets/environment values MUST resolve them through an explicit, ordered search order before failing. This prevents implicit environment drift and makes local/CI behavior deterministic.</p><h3 id="canonical-discovery-order-hard-requirement" tabindex="-1">Canonical discovery order (hard requirement) <a class="header-anchor" href="#canonical-discovery-order-hard-requirement" aria-label="Permalink to &quot;Canonical discovery order (hard requirement)&quot;">​</a></h3><ol><li>In-process explicit environment variables.</li><li>Workspace-specific overrides in the current repo (<code>.env</code>, <code>.env.local</code>).</li><li>Canonical project-level <code>atoms.tech</code> env files in the sibling <code>clean/deploy/atoms.tech</code> workspace: <ul><li><code>../clean/deploy/atoms.tech/.env.local</code></li><li><code>../clean/deploy/atoms.tech/.env</code></li></ul></li><li>Upward workspace fallback <code>atoms.tech/.env</code> siblings when present in parent locations.</li><li><code>config/secrets.yml</code> (repo-level secret file when allowed by deployment mode).</li></ol><h3 id="hard-fail-check-definition" tabindex="-1">Hard-fail check definition <a class="header-anchor" href="#hard-fail-check-definition" aria-label="Permalink to &quot;Hard-fail check definition&quot;">​</a></h3><p>The contract is now executable and SHALL fail hard when required variables are missing.</p><ul><li>Required for <code>atoms-mcp-prod</code> canonical deploy: <ul><li><code>SUPABASE_URL</code></li><li><code>SUPABASE_KEY</code></li><li><code>FASTMCP_SERVER_AUTH_AUTHKITPROVIDER_AUTHKIT_DOMAIN</code></li><li><code>FASTMCP_SERVER_AUTH_AUTHKITPROVIDER_BASE_URL</code></li><li><code>WORKOS_API_KEY</code></li><li><code>WORKOS_CLIENT_ID</code></li><li><code>CRON_SECRET</code></li></ul></li><li>Required for <code>atomsAgent</code> canonical deploy: <ul><li><code>ATOMS_SECRET_AUTHKIT_JWKS_URL</code></li><li><code>ATOMS_SECRET_SUPABASE_URL</code></li><li><code>ATOMS_SECRET_SUPABASE_KEY</code></li><li><code>ATOMS_SECRET_VERTEX_PROJECT_ID</code></li><li><code>ATOMS_SECRET_VERTEX_LOCATION</code></li></ul></li></ul><p>Legacy or optional variables (for debug/local workflows only) must never be treated as canonical gates.</p><p>Operational check command:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/validate_atoms_env_discovery.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atoms-mcp-prod</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/validate_atoms_env_discovery.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atomsagent</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Contract checks fail with non-zero exit codes and emit strict error details for the missing variable and the expected source path.</p><h3 id="contract-implementation-notes" tabindex="-1">Contract implementation notes <a class="header-anchor" href="#contract-implementation-notes" aria-label="Permalink to &quot;Contract implementation notes&quot;">​</a></h3><ul><li><code>agentapi/atomsAgent/scripts/generate_supabase_models.py</code> follows this ordered fallback for env and secret lookup and remains the operational reference for DB model tooling.</li><li><code>thegent/scripts/validate_atoms_env_discovery.py</code> is the canonical hard-fail checker used by the gent for pre-deploy/CI validation.</li><li>CI/ops tasks should treat missing mandatory environment variables as hard failures once this contract scope is invoked.</li><li>Future env loader changes in sibling repos must update this section and the checker together in the same task.</li></ul><h2 id="operational-check" tabindex="-1">Operational Check <a class="header-anchor" href="#operational-check" aria-label="Permalink to &quot;Operational Check&quot;">​</a></h2><p>Before any release-like cleanup/deploy operation:</p><ol><li>Verify the target repo path matches the canonical entry above.</li><li>Verify the command matches canonical clean/deploy operation.</li><li>Verify env inputs are present in at least one allowed source from the contract.</li><li>If env resolution requires additional sources, update this contract and source code together in the same task.</li></ol>',31)])])}const u=a(n,[["render",l]]);export{m as __pageData,u as default};
